# This init script prepares service on Onyxia.
# Purpose: {"chart_id":"vscode-python","purpose":"Database processing with statistical summary (mean, sum, categories) output in terminal","files":{"main.py":"\"\"\"\nDatabase Statistical Summary\n============================\nConnects to a database, processes the data, and outputs a summary table\nwith mean, sum, and category counts in the terminal.\n\nUsage:\n    python main.py\n\nConfiguration:\n    Edit the DATABASE_URL below to point to your database.\n    Supported: SQLite, PostgreSQL, MySQL, etc. (via SQLAlchemy)\n\"\"\"\n\nimport pandas as pd\nfrom sqlalchemy import create_engine, text\n\n# ============================================================\n# CONFIGURATION - Edit this to point to your database\n# ============================================================\n# Examples:\n#   SQLite:       \"sqlite:///data/sample.db\"\n#   PostgreSQL:   \"postgresql://user:password@host:5432/dbname\"\n#   MySQL:        \"mysql+pymysql://user:password@host:3306/dbname\"\n# ============================================================\nDATABASE_URL = \"sqlite:///data/sample.db\"\n\n# Table or query to analyze\nTABLE_OR_QUERY = \"SELECT * FROM main_table\"\n\n\ndef create_sample_database():\n    \"\"\"Create a sample SQLite database for demonstration purposes.\"\"\"\n    import sqlite3\n    import os\n\n    os.makedirs(\"data\", exist_ok=True)\n    db_path = \"data/sample.db\"\n\n    if os.path.exists(db_path):\n        print(f\"[INFO] Sample database already exists at {db_path}\")\n        return\n\n    conn = sqlite3.connect(db_path)\n    cursor = conn.cursor()\n\n    cursor.execute(\"\"\"\n        CREATE TABLE IF NOT EXISTS main_table (\n            id INTEGER PRIMARY KEY,\n            category TEXT NOT NULL,\n            amount REAL NOT NULL,\n            quantity INTEGER NOT NULL,\n            region TEXT NOT NULL\n        )\n    \"\"\")\n\n    # Insert sample data\n    sample_data = [\n        (1, 'Electronics', 299.99, 3, 'North'),\n        (2, 'Electronics', 149.50, 7, 'South'),\n        (3, 'Clothing', 45.00, 12, 'North'),\n        (4, 'Clothing', 89.99, 5, 'East'),\n        (5, 'Food', 12.50, 30, 'West'),\n        (6, 'Food', 8.75, 45, 'North'),\n        (7, 'Electronics', 599.00, 2, 'East'),\n        (8, 'Clothing', 25.00, 18, 'South'),\n        (9, 'Food', 22.30, 15, 'West'),\n        (10, 'Electronics', 79.99, 9, 'North'),\n        (11, 'Clothing', 120.00, 4, 'East'),\n        (12, 'Food', 5.50, 60, 'South'),\n    ]\n\n    cursor.executemany(\n        \"INSERT INTO main_table (id, category, amount, quantity, region) VALUES (?, ?, ?, ?, ?)\",\n        sample_data\n    )\n    conn.commit()\n    conn.close()\n    print(f\"[INFO] Sample database created at {db_path}\")\n\n\ndef load_data(database_url: str, query: str) -> pd.DataFrame:\n    \"\"\"Load data from the database into a DataFrame.\"\"\"\n    engine = create_engine(database_url)\n    df = pd.read_sql_query(text(query), engine)\n    engine.dispose()\n    return df\n\n\ndef compute_summary(df: pd.DataFrame) -> pd.DataFrame:\n    \"\"\"Compute statistical aggregates: mean, sum, and category counts.\"\"\"\n    # Identify numeric and categorical columns\n    numeric_cols = df.select_dtypes(include='number').columns.tolist()\n    categorical_cols = df.select_dtypes(include='object').columns.tolist()\n\n    # --- Numeric aggregates: mean and sum ---\n    numeric_summary = df[numeric_cols].agg(['mean', 'sum']).T\n    numeric_summary.columns = ['mean', 'sum']\n    numeric_summary['type'] = 'numeric'\n    numeric_summary = numeric_summary.reset_index().rename(columns={'index': 'column'})\n\n    # --- Categorical aggregates: unique count and top category ---\n    cat_summary = pd.DataFrame({\n        'column': categorical_cols,\n        'unique_count': [df[col].nunique() for col in categorical_cols],\n        'top_category': [df[col].value_counts().index[0] if df[col].nunique() > 0 else 'N/A' for col in categorical_cols],\n        'top_count': [df[col].value_counts().iloc[0] if df[col].nunique() > 0 else 0 for col in categorical_cols],\n    })\n    cat_summary['type'] = 'categorical'\n\n    # --- Category breakdown per categorical column ---\n    category_breakdowns = []\n    for col in categorical_cols:\n        vc = df[col].value_counts()\n        for cat, count in vc.items():\n            category_breakdowns.append({\n                'column': col,\n                'category': cat,\n                'count': count,\n                'percentage': f\"{count / len(df) * 100:.1f}%\"\n            })\n\n    return numeric_summary, cat_summary, pd.DataFrame(category_breakdowns)\n\n\ndef print_report(df: pd.DataFrame):\n    \"\"\"Print the full statistical summary report to the terminal.\"\"\"\n    print(\"\\n\" + \"=\" * 60)\n    print(\"  DATABASE STATISTICAL SUMMARY\")\n    print(\"=\" * 60)\n\n    print(f\"\\n  Rows: {len(df)}\")\n    print(f\"  Columns: {len(df.columns)}\")\n    print(f\"  Columns: {', '.join(df.columns.tolist())}
